"""Differential check: impact(service, full-identity) == filtered impact(service)."""
import random
import sys

sys.path.insert(0, ".")
from supply_guard.catalog import Catalog


def osv_record(vid, pkg, versions, severity=None, source_only=False):
    rec = {
        "id": vid,
        "affected": [
            {"package": {"ecosystem": "PyPI", "name": pkg}, "versions": list(versions)}
        ],
    }
    if severity is not None:
        rec["database_specific"] = {"severity": severity}
    return rec


def record_key(record):
    return (
        record["component"]["service"],
        record["component"]["ecosystem"],
        record["component"]["name"],
        record["component"]["version"],
        record["vulnerability"],
        record["source"],
        record["matched_name"],
    )


def run_trial(seed):
    rng = random.Random(seed)
    catalog = Catalog()
    n = rng.randint(1, 18)
    names = [f"pkg{chr(97 + i)}" for i in range(n)]
    versions_pool = ["1.0.0", "2.0.0", "2.0.0+local", "1.5"]

    for i in range(n):
        version = rng.choice(versions_pool)
        catalog.add_component("svc", "pypi", names[i], version)

    # Random dependency DAG + a few cycle-creating edges.
    for i in range(n):
        for j in range(i + 1, n):
            if rng.random() < 0.28:
                catalog.add_dependency(
