"""Differential check: impact(service, full-identity) == filtered impact(service)."""
import random
import sys

sys.path.insert(0, ".")
from supply_guard.catalog import Catalog


def osv_record(vid, pkg, versions, severity=None, source_only=False):
    rec = {
        "id": vid,
        "affected": [
            {"package": {"ecosystem": "PyPI", "name": pkg}, "versions": list(versions)}
        ],
    }
    if severity is not None:
        rec["database_specific"] = {"severity": severity}
    return rec


def record_key(record):
    return (
        record["component"]["service"],
        record["component"]["ecosystem"],
        record["component"]["name"],
        record["component"]["version"],
        record["vulnerability"],
        record["source"] if record["source"] is not None else "",
        record["matched_name"],
    )


def run_trial(seed):
    rng = random.Random(seed)
    catalog = Catalog()
    n = rng.randint(1, 18)
    names = [f"pkg{chr(97 + i)}" for i in range(n)]
    versions_pool = ["1.0.0", "2.0.0", "2.0.0+local", "1.5"]

    for i in range(n):
        version = rng.choice(versions_pool)
        catalog.add_component("svc", "pypi", names[i], version)

    # Random dependency DAG + a few cycle-creating edges.
    for i in range(n):
        for j in range(i + 1, n):
            if rng.random() < 0.28:
                catalog.add_dependency(
                    "svc", "pypi", names[i], catalog_comp_version(catalog, names[i]),
                    "svc", "pypi", names[j], catalog_comp_version(catalog, names[j]),
                )
    # Extra back edges to make cycles.
    if n >= 2:
        for _ in range(rng.randint(0, 3)):
            i, j = rng.sample(range(n), 2)
        try:
            catalog.add_dependency(
                "svc", "pypi", names[j], catalog_comp_version(catalog, names[j]),
                "svc", "pypi", names[i], catalog_comp_version(catalog, names[i]),
            )
        except ValueError:
            pass

    # Manual vulnerabilities on raw names.
    for name in rng.sample(names, rng.randint(0, min(4, n))):
        catalog.add_vulnerability(f"MAN-{name}", name, rng.choice(
            ["low", "medium", "high", "critical"]))

    # Imported OSV: multiple sources, same id across sources, normalized names.
    catalog.import_osv(
        "srcA",
        [osv_record("CVE-X", "PkGb", ["1.0.0"], "high"),
         osv_record("CVE-Y", "PkgC", ["2.0.0", "1.5"])],
    )
    catalog.import_osv(
        "srcB",
        [osv_record("CVE-X", "pkgb", ["1.0.0"], "low"),
         osv_record("CVE-Z", "pkga", ["1.0.0", "2.0.0", "2.0.0+local", "1.5"])],
    )
    # Manual vuln sharing an id with an imported one: must stay distinct.
    catalog.add_vulnerability("CVE-X", "pkgb", "medium")

    service_records = catalog.impact(service="svc")
    by_component = {}
    for record in service_records:
        by_component.setdefault(
            (record["component"]["ecosystem"], record["component"]["name"],
             record["component"]["version"]),
            [],
        ).append(record)

    # One record per (component, vuln, source, matched package).
    keys = [record_key(r) for r in service_records]
    assert len(keys) == len(set(keys)), f"seed {seed}: duplicate records in service query"

    for (eco, cname, cver), expected in by_component.items():
        got = catalog.impact(
            service="svc", ecosystem=eco, name=cname, version=cver
        )
        assert len(got) == len(expected), (
            f"seed {seed}: count mismatch for {cname} {cver}: "
            f"{len(got)} != {len(expected)}"
        )
        got_sorted = sorted(got, key=record_key)
        exp_sorted = sorted(expected, key=record_key)
        for g, e in zip(got_sorted, exp_sorted):
            assert g == e, (
                f"seed {seed}: record mismatch for {cname} {cver}\n got={g}\n exp={e}"
            )

    # Targets not present return [].
    assert catalog.impact(service="svc", ecosystem="pypi",
                          name="ghost", version="9.9.9") == []
    # Existing component identity with wrong version: empty, no error.
    assert catalog.impact(service="svc", ecosystem="pypi",
                          name=names[0], version="0.0.1") == []
    catalog.close()


def catalog_comp_version(catalog, name):
    row = catalog.connection.execute(
        "SELECT version FROM components WHERE service='svc' AND name=?", (name,)
    ).fetchone()
    return str(row["version"])


if __name__ == "__main__":
    for seed in range(300):
        run_trial(seed)
    print("differential parity OK over 300 random graphs")

